package admin

import _ "embed"

//go:embed permissions.js
var permissionsJS string

const permissionTemplate = `{{define "permissions"}}
{{if .Legacy}}<p class="warning" data-legacy-warning>Shared access follows globally enabled tools. Choose Restricted to edit an exact tool list. Saving Restricted replaces shared access with only the checked tools.</p>{{end}}
<p data-permission-status role="status" aria-live="polite">{{.Message}}</p>
<form method="post" action="{{.Base}}/admin/connection/permissions/{{.Principal}}" data-permissions data-uncertain="{{.Uncertain}}" data-draft="{{if .Message}}true{{else}}false{{end}}"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}">
<div class="permission-policy"><label>Access policy<select name="policy">{{if .Legacy}}<option value="legacy_shared" {{if eq .Policy "legacy_shared"}}selected{{end}}>Legacy shared (existing access)</option>{{end}}<option value="restricted" {{if eq .Policy "restricted"}}selected{{end}}>Restricted — exact selected tools only</option></select></label><p>Global switches bound availability. Newly discovered tools are never added automatically.</p></div>
<div class="permission-toolbar"><label class="sr" for="permission-search">Search servers and tools</label><input type="search" id="permission-search" placeholder="Search servers and tools…"><div class="permission-actions"><button type="button" data-allow-visible>Allow visible</button><button type="button" data-deny-visible>Deny visible</button><span data-draft-count>Saved permissions</span><button type="submit" class="primary" {{if .Uncertain}}disabled{{end}}>Save permissions</button></div></div>
{{range $i,$group:=.Groups}}<details class="permission-group" data-permission-group data-server="{{.Server}}" {{if eq $i 0}}open{{end}}><summary><input type="checkbox" data-permission-group-select disabled aria-label="Allow visible tools on {{.Server}}"><b>{{.Server}}</b><span data-group-grant-count></span></summary><div class="table-wrap"><table><thead><tr><th>Tool</th><th>Global availability</th><th>Current policy</th><th>Argument constraints</th></tr></thead><tbody>{{range .Rows}}<tr data-permission-row data-search="{{.Server}} {{.Tool}}"><td><label><input type="checkbox" name="{{.Field}}" value="1" {{if .Selected}}checked{{end}} {{if eq $.Policy "legacy_shared"}}disabled{{end}}> {{.Tool}}</label></td><td data-label="Global availability">{{if .Enabled}}Enabled{{else}}Disabled{{end}}</td><td data-policy-cell data-label="Current policy">{{if .Allowed}}Allowed{{else}}Denied{{end}}</td><td data-label="Argument constraints"><code>{{.Constraints}}</code></td></tr>{{end}}</tbody></table></div></details>{{end}}
<p class="muted">Group controls affect matching tools only. Hidden permissions are preserved. No checked tools means no access in Restricted mode.</p><noscript><p>Group buttons require JavaScript. Select individual tools and save the form to apply permissions.</p></noscript></form><p class="page-foot">Registry revision <span data-permission-revision>{{.Revision}}</span></p><a class="reload-link" href="{{.Base}}/admin/connection/permissions/{{.Principal}}">Reload saved permissions (discards draft)</a>
{{end}}`
